ALTER TABLE "stages" ADD COLUMN "agent_goal" text DEFAULT '' NOT NULL;--> statement-breakpoint
-- Existing funnels still carry the default stage names with empty texts. Fill the goal and,
-- where the owner left it empty, the description, so the agent knows which step of the sale
-- it is on without anyone opening the funnel settings. Kept equal to DEFAULT_STAGES in
-- src/lib/funnel.ts by test/stage-goal-migration.test.ts.
UPDATE "stages" s
SET "agent_goal" = d.goal,
    "description" = CASE WHEN btrim(s."description") = '' THEN d.description ELSE s."description" END
FROM (VALUES
  ('Новый лид', 'Клиент только написал: поздоровался или задал первый вопрос. Что ему нужно, ещё не ясно.', 'Поздоровайся и узнай, что нужно клиенту. Если он сразу задал вопрос — ответь на него и задай один уточняющий вопрос о его задаче. Не спрашивай, будет ли заказ, и не говори об оплате.'),
  ('В диалоге', 'Клиент отвечает и рассказывает, что ему нужно, но конкретный товар или вариант ещё не выбран.', 'Выясни потребность: что именно нужно, для чего, какой вариант. Отвечай на вопросы клиента по базе знаний. О заказе и оплате не спрашивай.'),
  ('Интерес проявлен', 'Клиент спрашивает о конкретном товаре или услуге: цена, сроки, доставка, варианты.', 'Ответь на вопрос клиента и помоги выбрать подходящий вариант. Уточняй недостающее по одному вопросу. О заказе и оплате пока не спрашивай.'),
  ('Квалифицирован', 'Понятно, что именно нужно клиенту: товар или вариант, количество, город.', 'Предложи конкретный вариант с ценой из базы знаний и спроси, подходит ли он клиенту.'),
  ('Предложение отправлено', 'Клиенту назвали конкретный вариант и цену, он думает или задаёт вопросы.', 'Ответь на сомнения и вопросы. Когда клиенту всё подходит — спроси, оформляем ли заказ.'),
  ('Готов к покупке', 'Клиент сказал, что берёт, и согласовал, что именно заказывает.', 'Подтверди состав заказа, назови итоговую сумму и уточни данные для доставки. Затем предложи способ оплаты.'),
  ('Заказано', 'Заказ согласован, клиенту дали способ оплаты, ждём оплату.', 'Помоги клиенту оплатить по инструкциям владельца. Никогда не говори, что оплата получена.'),
  ('Оплачено', 'Оплата подтверждена.', 'Поблагодари клиента и расскажи, что будет дальше: сроки и получение заказа.'),
  ('Отказ', 'Клиент отказался от покупки.', 'Вежливо прими решение клиента, можно спросить причину. Не дави и не уговаривай.')
) AS d(name, description, goal)
WHERE btrim(s."name") = d.name AND s."agent_goal" = '';
